head.b:skin:
:root{
  --cream:#F5F0E7;--paper:#FFFCF7;--ink:#22211E;--muted:#706B63;--terra:#C95545;
  --sage:#A7B39F;--line:#DED6C9;--shadow:0 10px 30px rgba(34,33,30,.07);--radius:18px
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--cream);color:var(--ink);font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.65}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%;height:auto}
.wrap{width:min(1180px,92vw);margin:0 auto}
.topline{border-top:3px solid var(--ink);border-bottom:1px solid var(--line);padding:9px 0;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.masthead{padding:30px 0 24px;display:flex;align-items:flex-end;justify-content:space-between;gap:24px}
.brand{font-size:42px;font-weight:900;letter-spacing:-.055em;line-height:.95}
.brand-sub{margin-top:9px;font-size:11px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--muted)}
.search-link{display:inline-flex;align-items:center;gap:8px;border:1px solid #CBC2B4;background:var(--paper);border-radius:999px;padding:11px 17px;font-size:13px;font-weight:700}
.search-link:hover{border-color:var(--ink)}
.nav-area{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:14px 0 16px;background:rgba(255,252,247,.38)}
.nav-grid{display:flex;flex-wrap:wrap;gap:10px}
.nav-pill{display:inline-flex;align-items:center;gap:8px;background:var(--paper);border:1px solid #D8D0C4;border-radius:999px;padding:9px 13px;font-size:13px;font-weight:600;line-height:1;white-space:nowrap;transition:transform .15s ease,border-color .15s ease,background .15s ease}
.nav-pill:hover{transform:translateY(-1px);border-color:var(--terra);background:#fff}
.nav-icon{width:23px;height:23px;display:inline-grid;place-items:center;border-radius:50%;background:#ECE5DA;font-size:14px;flex:0 0 23px}

.hero{padding:34px 0 24px;display:grid;grid-template-columns:1.45fr .55fr;gap:22px}
.hero-main{position:relative;min-height:470px;border-radius:var(--radius);overflow:hidden;background:#D9D2C7}
.hero-main img{width:100%;height:100%;object-fit:cover}
.hero-overlay{position:absolute;left:0;right:0;bottom:0;padding:46px 42px 38px;color:#fff;background:linear-gradient(to top,rgba(0,0,0,.78),rgba(0,0,0,0))}
.eyebrow{font-size:11px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}
.hero-overlay h1{margin:8px 0 10px;font-family:Georgia,'Times New Roman',serif;font-size:clamp(44px,5.5vw,76px);line-height:.96;letter-spacing:-.045em;max-width:760px}
.hero-overlay p{margin:0;max-width:650px;font-size:18px}
.side-stack{display:grid;gap:22px}
.side-card{display:flex;flex-direction:column;justify-content:flex-end;min-height:224px;border-radius:var(--radius);background:var(--paper);box-shadow:var(--shadow);padding:29px}
.side-card .label{display:inline-block;width:max-content;background:var(--sage);border-radius:999px;padding:6px 10px;font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
.side-card h2{margin:11px 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:31px;line-height:1.02;letter-spacing:-.03em}
.side-card p{margin:0;color:var(--muted);font-size:14px}

.section{padding:28px 0}
.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:16px}
.section-head h2{margin:0;font-family:Georgia,'Times New Roman',serif;font-size:37px;line-height:1.02;letter-spacing:-.04em}
.section-head a{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--terra)}
.article-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.article-card{background:var(--paper);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow)}
.article-card .thumb{aspect-ratio:4/3;background:#DDD5C9;overflow:hidden}
.article-card .thumb img{width:100%;height:100%;object-fit:cover}
.article-card .body{padding:18px 19px 22px}
.meta{color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase}
.article-card h3{margin:9px 0 0;font-family:Georgia,'Times New Roman',serif;font-size:27px;line-height:1.05;letter-spacing:-.03em}

.topic-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.topic-card{background:var(--paper);border:1px solid #E0D8CC;border-radius:16px;padding:20px;min-height:136px;display:flex;flex-direction:column;justify-content:space-between}
.topic-card:hover{border-color:var(--terra);box-shadow:var(--shadow)}
.topic-num{color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.14em}
.topic-name{font-family:Georgia,'Times New Roman',serif;font-size:23px;line-height:1.05}

.dark-band{margin:30px 0 10px;background:var(--ink);color:#fff;border-radius:var(--radius);padding:34px 36px;display:flex;align-items:center;justify-content:space-between;gap:28px}
.dark-band h2{margin:0 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:34px;line-height:1.05}
.dark-band p{margin:0;color:#D2CEC5}
.dark-band a{flex:0 0 auto;background:#fff;color:var(--ink);border-radius:999px;padding:12px 17px;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}

.content{padding:52px 0;display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:38px}
.post-header .label{color:var(--terra);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
.post-header h1{margin:8px 0 14px;font-family:Georgia,'Times New Roman',serif;font-size:clamp(44px,6vw,72px);line-height:.96;letter-spacing:-.05em}
.post-header .meta{margin-bottom:25px}
.post-body{font-size:18px;line-height:1.82}
.post-body h2,.post-body h3{font-family:Georgia,'Times New Roman',serif;line-height:1.12;letter-spacing:-.025em}
.post-body h2{font-size:35px;margin:46px 0 12px}
.post-body h3{font-size:27px;margin:34px 0 10px}
.post-body blockquote{margin:28px 0;padding:18px 20px;border-left:4px solid var(--terra);background:var(--paper);border-radius:0 14px 14px 0}
.post-body img{border-radius:16px;margin:26px 0}
.sidebar{position:sticky;top:20px;height:max-content}
.sidebox{background:var(--paper);border:1px solid #E0D8CC;border-radius:16px;padding:21px;margin-bottom:15px}
.sidebox h3{margin:0 0 11px;font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}
.sidebox ul{list-style:none;padding:0;margin:0}
.sidebox li{padding:8px 0;border-bottom:1px solid var(--line);font-size:14px}

.footer{margin-top:65px;background:#1D1C19;color:#F4F1EA;padding:50px 0}
.footer-grid{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:38px}
.footer h3{margin:0 0 10px;font-family:Georgia,'Times New Roman',serif;font-size:34px;line-height:1}
.footer p,.footer a{color:#BDB8AF;font-size:14px}
.footer-links{display:grid;gap:7px}
.copyright{margin-top:34px;padding-top:18px;border-top:1px solid #35332F;color:#8F8A82;font-size:11px}

@media(max-width:980px){
  .hero{grid-template-columns:1fr}.hero-main{min-height:440px}.article-grid{grid-template-columns:repeat(2,1fr)}.topic-grid{grid-template-columns:repeat(2,1fr)}.content{grid-template-columns:1fr}.sidebar{position:static}.footer-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:640px){
  body{font-size:15px}.brand{font-size:32px}.brand-sub{font-size:9px;letter-spacing:.16em}.masthead{padding:24px 0 20px}.search-link{display:none}.nav-pill{font-size:12px;padding:8px 11px}.nav-icon{width:21px;height:21px;flex-basis:21px;font-size:13px}.hero{padding-top:22px}.hero-main{min-height:390px}.hero-overlay{padding:30px 24px 26px}.hero-overlay h1{font-size:43px}.hero-overlay p{font-size:15px}.side-card h2{font-size:27px}.article-grid{grid-template-columns:1fr}.topic-grid{grid-template-columns:1fr 1fr}.section-head h2{font-size:31px}.dark-band{display:block;padding:28px}.dark-band a{display:inline-block;margin-top:18px}.footer-grid{grid-template-columns:1fr}.content{padding:35px 0}.post-header h1{font-size:45px}.post-body{font-size:17px}
}
